CREATE     PROCEDURE [synapse_fo].[usp_Update_CUSTTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:35
	Description: Update stored procedure for CUSTTRANS from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTINGEVENT] = stg.[ACCOUNTINGEVENT],
		tgt.[ACCOUNTNUM] = stg.[ACCOUNTNUM],
		tgt.[AMOUNTCUR] = stg.[AMOUNTCUR],
		tgt.[AMOUNTMST] = stg.[AMOUNTMST],
		tgt.[APPROVED] = stg.[APPROVED],
		tgt.[APPROVER] = stg.[APPROVER],
		tgt.[BANKCENTRALBANKPURPOSECODE] = stg.[BANKCENTRALBANKPURPOSECODE],
		tgt.[BANKCENTRALBANKPURPOSETEXT] = stg.[BANKCENTRALBANKPURPOSETEXT],
		tgt.[BANKLCEXPORTLINE] = stg.[BANKLCEXPORTLINE],
		tgt.[BANKREMITTANCEFILEID] = stg.[BANKREMITTANCEFILEID],
		tgt.[BILLOFEXCHANGEID] = stg.[BILLOFEXCHANGEID],
		tgt.[BILLOFEXCHANGESEQNUM] = stg.[BILLOFEXCHANGESEQNUM],
		tgt.[BILLOFEXCHANGESTATUS] = stg.[BILLOFEXCHANGESTATUS],
		tgt.[CANCELLEDPAYMENT] = stg.[CANCELLEDPAYMENT],
		tgt.[CASHDISCBASEDATE] = stg.[CASHDISCBASEDATE],
		tgt.[CASHDISCCODE] = stg.[CASHDISCCODE],
		tgt.[CASHPAYMENT] = stg.[CASHPAYMENT],
		tgt.[CLOSED] = stg.[CLOSED],
		tgt.[COLLECTIONLETTER] = stg.[COLLECTIONLETTER],
		tgt.[COLLECTIONLETTERCODE] = stg.[COLLECTIONLETTERCODE],
		tgt.[COMPANYBANKACCOUNTID] = stg.[COMPANYBANKACCOUNTID],
		tgt.[CONTROLNUM] = stg.[CONTROLNUM],
		tgt.[CORRECT] = stg.[CORRECT],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CREATEDTRANSACTIONID] = stg.[CREATEDTRANSACTIONID],
		tgt.[CREDMANEXCLUDEFROMCREDITCONTROL] = stg.[CREDMANEXCLUDEFROMCREDITCONTROL],
		tgt.[CURRENCYCODE] = stg.[CURRENCYCODE],
		tgt.[CUSTAUTOMATIONEXCLUDE] = stg.[CUSTAUTOMATIONEXCLUDE],
		tgt.[CUSTAUTOMATIONPREDICTIONSENT] = stg.[CUSTAUTOMATIONPREDICTIONSENT],
