		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[MODIFIEDTRANSACTIONID] = stg.[MODIFIEDTRANSACTIONID],
		tgt.[OFFSETRECID] = stg.[OFFSETRECID],
		tgt.[ORDERACCOUNT] = stg.[ORDERACCOUNT],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PAYMID] = stg.[PAYMID],
		tgt.[PAYMMETHOD] = stg.[PAYMMETHOD],
		tgt.[PAYMMODE] = stg.[PAYMMODE],
		tgt.[PAYMREFERENCE] = stg.[PAYMREFERENCE],
		tgt.[PAYMSCHEDID] = stg.[PAYMSCHEDID],
		tgt.[PAYMSPEC] = stg.[PAYMSPEC],
		tgt.[PAYMTERMID] = stg.[PAYMTERMID],
		tgt.[POSTINGPROFILE] = stg.[POSTINGPROFILE],
		tgt.[POSTINGPROFILECLOSE] = stg.[POSTINGPROFILECLOSE],
		tgt.[PREPAYMENT] = stg.[PREPAYMENT],
		tgt.[REASONREFRECID] = stg.[REASONREFRECID],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REPORTINGCURRENCYAMOUNT] = stg.[REPORTINGCURRENCYAMOUNT],
		tgt.[REPORTINGCURRENCYCROSSRATE] = stg.[REPORTINGCURRENCYCROSSRATE],
		tgt.[REPORTINGCURRENCYEXCHRATE] = stg.[REPORTINGCURRENCYEXCHRATE],
		tgt.[REPORTINGCURRENCYEXCHRATESECONDARY] = stg.[REPORTINGCURRENCYEXCHRATESECONDARY],
		tgt.[REPORTINGEXCHADJUSTMENTREALIZED] = stg.[REPORTINGEXCHADJUSTMENTREALIZED],
		tgt.[REPORTINGEXCHADJUSTMENTUNREALIZED] = stg.[REPORTINGEXCHADJUSTMENTUNREALIZED],
		tgt.[RETAILCUSTTRANS] = stg.[RETAILCUSTTRANS],
		tgt.[RETAILSTOREID] = stg.[RETAILSTOREID],
		tgt.[RETAILTERMINALID] = stg.[RETAILTERMINALID],
		tgt.[RETAILTRANSACTIONID] = stg.[RETAILTRANSACTIONID],
		--tgt.[RICSPAYMENTSTATE] = stg.[RICSPAYMENTSTATE],
		--tgt.[RICSPAYMENTSTATUS] = stg.[RICSPAYMENTSTATUS],
		tgt.[SETTLEAMOUNT_MX] = stg.[SETTLEAMOUNT_MX],
		tgt.[SETTLEAMOUNTCUR] = stg.[SETTLEAMOUNTCUR],
		tgt.[SETTLEAMOUNTMST] = stg.[SETTLEAMOUNTMST],
		tgt.[SETTLEAMOUNTREPORTING] = stg.[SETTLEAMOUNTREPORTING],
		tgt.[SETTLEMENT] = stg.[SETTLEMENT],
		--tgt.[SKS_BR_DDR_ISSELECTED] = stg.[SKS_BR_DDR_ISSELECTED],
		--tgt.[SKS_DD_ISDIRECTDEBIT] = stg.[SKS_DD_ISDIRECTDEBIT],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXINVOICESALESID] = stg.[TAXINVOICESALESID],
		tgt.[THIRDPARTYBANKACCOUNTID] = stg.[THIRDPARTYBANKACCOUNTID],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[TRANSTYPE] = stg.[TRANSTYPE],
		tgt.[TXT] = stg.[TXT],
		tgt.[VOUCHER] = stg.[VOUCHER]
	 FROM [synapse_fo].[CUSTTRANS] tgt
		INNER JOIN [staging_fo].[CUSTTRANS] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
